-- Run once in Supabase SQL Editor. Create your admin user in Auth > Users,
-- then INSERT its UUID into portfolio_admins using the service SQL editor.
create extension if not exists pgcrypto;
create table if not exists public.portfolio_admins(user_id uuid primary key references auth.users(id) on delete cascade);
create or replace function public.is_portfolio_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.portfolio_admins where user_id=(select auth.uid()))$$;
revoke all on function public.is_portfolio_admin() from public;
grant execute on function public.is_portfolio_admin() to authenticated;
create table if not exists public.profiles(id integer primary key default 1 check(id=1),name text not null default 'Perry Dave Geron',title text default 'Senior Data Analyst',tagline text default '',bio text default '',about text default '',location text default 'Philippines',email text default '',linkedin text default '',github text default 'https://github.com/geronpd09',resume_url text default '',photo_url text default '',updated_at timestamptz not null default now());
insert into public.profiles(id,name,title,tagline,bio,about,location) values(1,'Perry Dave Geron','Senior Data Analyst','Workforce Analytics | Business Intelligence & Automation','I turn complex data into useful insights, build dashboards, and develop automation tools that help teams work smarter.','Over 10 years of experience in data operations, compensation and workforce analytics, reporting, dashboard development, and process automation.','Philippines') on conflict(id) do nothing;
create table if not exists public.work_experiences(id uuid primary key default gen_random_uuid(),company text not null,position text not null,employment_type text,location text,start_date date,end_date date,is_current boolean not null default false,summary text,responsibilities text[] not null default '{}',skills text[] not null default '{}',achievements text[] not null default '{}',logo_path text,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),title text not null,date date,category text,description text,image_path text,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.skills(id uuid primary key default gen_random_uuid(),name text not null,category text,description text,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.certifications(id uuid primary key default gen_random_uuid(),title text not null,issuer text,issue_date date,expiration_date date,credential_id text,credential_url text,file_path text,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),title text not null,category text,date date,description text,problem text,solution text,impact text,technologies text[] not null default '{}',image_path text,github_url text,demo_url text,featured boolean not null default false,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.portfolio_videos(id uuid primary key default gen_random_uuid(),title text not null,category text,description text,video_path text,thumbnail_path text,project_id uuid references public.projects(id) on delete set null,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['profiles','work_experiences','achievements','skills','certifications','projects','portfolio_videos'] loop if t<>'portfolio_videos' then execute format('create trigger touch_%I before update on public.%I for each row execute function public.touch_updated_at()',t,t);end if;end loop;end$$;
do $$declare t text;begin foreach t in array array['profiles','work_experiences','achievements','skills','certifications','projects','portfolio_videos'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy public_read_%I on public.%I for select to anon,authenticated using (%s)',t,t,case when t='profiles' then 'true' else 'published = true or (select public.is_portfolio_admin())' end);execute format('create policy admin_insert_%I on public.%I for insert to authenticated with check ((select public.is_portfolio_admin()))',t,t);execute format('create policy admin_update_%I on public.%I for update to authenticated using ((select public.is_portfolio_admin())) with check ((select public.is_portfolio_admin()))',t,t);execute format('create policy admin_delete_%I on public.%I for delete to authenticated using ((select public.is_portfolio_admin()))',t,t);end loop;end$$;
alter table public.portfolio_admins enable row level security;
-- No client-side access to admin membership table; is_portfolio_admin() is security-definer.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolio-public','portfolio-public',true,10485760,array['image/png','image/jpeg','image/webp','application/pdf']) on conflict(id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolio-videos','portfolio-videos',true,52428800,array['video/mp4','video/webm']) on conflict(id) do nothing;
create policy portfolio_upload_images on storage.objects for insert to authenticated with check(bucket_id='portfolio-public' and (select public.is_portfolio_admin()));
create policy portfolio_update_images on storage.objects for update to authenticated using(bucket_id='portfolio-public' and (select public.is_portfolio_admin()));
create policy portfolio_delete_images on storage.objects for delete to authenticated using(bucket_id='portfolio-public' and (select public.is_portfolio_admin()));
create policy portfolio_upload_videos on storage.objects for insert to authenticated with check(bucket_id='portfolio-videos' and (select public.is_portfolio_admin()));
create policy portfolio_update_videos on storage.objects for update to authenticated using(bucket_id='portfolio-videos' and (select public.is_portfolio_admin()));
create policy portfolio_delete_videos on storage.objects for delete to authenticated using(bucket_id='portfolio-videos' and (select public.is_portfolio_admin()));
-- Public video objects can be opened by direct URL, including after unpublishing.
-- Use private storage and signed URLs for genuinely private or embargoed content.
-- Reaction counts are written only by the Edge Function (service-role).
create table if not exists public.experience_reactions(experience_id uuid not null references public.work_experiences(id) on delete cascade,visitor_hash text not null,reaction text not null check(reaction in ('like','dislike')),created_at timestamptz default now(),primary key(experience_id,visitor_hash));
create table if not exists public.reaction_counts(experience_id uuid primary key references public.work_experiences(id) on delete cascade,likes integer not null default 0,dislikes integer not null default 0);
alter table public.experience_reactions enable row level security;
alter table public.reaction_counts enable row level security;
create policy public_read_reaction_counts on public.reaction_counts for select to anon,authenticated using(true);
